/** 苏服办 URL 缺少字段时 toast 提示，返回是否有缺失 */
export const toastSfbMissingFieldsIfNeeded = () => {
  if (!isSfbLikeUrl()) return false
  const missing = getSfbMissingFieldLabels()
  if (!missing.length) return false
  // 仅缺手机号时给出绑定指引，其余缺失保持原拼接文案
  const onlyPhoneMissing = missing.length === 1 && missing[0] === SFB_FIELD_LABELS.phone
  const hint = onlyPhoneMissing ? SFB_PHONE_MISSING_HINT : `缺少${missing.join('、')}`
  cacheLog('[苏服办跳转] 缺失参数提示', { missing, hint })
  showToast(hint)
  return true
}

const maskMiddle = (value, headLen, tailLen) => {
  const text = `${value || ''}`
  if (!text) return '(空)'
  if (text.length <= headLen + tailLen) return '***'
  return `${text.slice(0, headLen)}***${text.slice(-tailLen)}`
}

const maskSfbIdentity = (key, value) => {
  if (!value) return '(空)'
  if (key === 'name') return maskMiddle(value, 1, 0)
  if (key === 'phone') return maskMiddle(value, 3, 4)
  if (key === 'idNumber') return maskMiddle(value, 3, 4)
  return '***'
}

/** 取 URL 上的原始密文参数（保留 + 被解码为空格的原样，脱敏后才可打印） */
