/**
 * 苏服办跳转链路日志：记录入口 URL、参数存在性与脱敏后的密文值，供协调三方排查跳转问题。
 * 纯日志，无副作用；密文一律按字段差异化脱敏，不输出完整身份信息。
 */
export const logSfbJumpContext = (source = 'unknown') => {
  /* #ifdef H5 */
  try {
    const rawUrl = window.location.href || ''
    const { searchParams, hashParams } = parseH5SearchParams()
    const masked = {}
    SFB_CHECK_KEYS.forEach((key) => {
      const raw = getRawH5Param(key)
      if (!raw) return
      masked[key] = key === 'token' ? maskMiddle(raw, 4, 4) : maskSfbIdentity(key, raw)
    })

    const presence = {}
    ;['token', 'name', 'idType', 'idNumber', 'phone', 'topicvoteid', 'complexId', 'houseId'].forEach(
      (key) => {
        presence[key] = !!getRawH5Param(key)
      }
    )

    const ua = `${navigator.userAgent || ''}`
    cacheLog(`[苏服办跳转] ${source}`, {
      href: rawUrl.split('?')[0],
      hash: `${window.location.hash || ''}`.split('?')[0],
      hasSearchQuery: !!`${searchParams}`,
      hasHashQuery: !!`${hashParams}`,
      paramPresence: presence,
      maskedParams: masked,
      missingFields: getSfbMissingFieldLabels(),
      isSfbLikeUrl: isSfbLikeUrl(),
      isSfbLoginEntry: isSfbLoginEntry(),
      referrer: document.referrer || '(空)',
      isAlipay: /AlipayClient|AliApp/i.test(ua),
      isHanweb: /hanweb/i.test(ua) && !/dtdreamweb/i.test(ua),
    })
  } catch (error) {
    console.warn('[苏服办跳转] 日志采集失败', error)
  }
  /* #endif */
}

